fields.InputDefinition:
{
  "goal": "After logging in, open an AssociationDemo entity via the left sidebar 'Search entities...' box: click the search box, type 'Events', then click the exact 'Events' node (do NOT expand the entity group/chevron). Once the grid loads, type the nonsense term 'zzqxnomatch' into the grid quick-filter box ('Filter records...'). Verify the grid responds with a clean empty/'no results'/'No Matching Rows' state - no rows match and no error is shown. Pages can take 10-30s to load in this resource-constrained environment - wait patiently, do not navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "A grid (or global search) was searched with the nonsense term 'zzqxnomatch'",
    "A clean 'no results' / 'No Matching Rows' empty-state is displayed with no matching rows",
    "No error messages, blank screens, or crash pages"
  ]
}
